// Authored alternatives. Styles are internal editing aids, never labels shown to players.
export const DIALOGUE_REVISION = 2;
const rows = text => Object.fromEntries(text.trim().split('\n').map(line => {
  const [number,...parts]=line.split('|');
  if(parts.length!==8)throw new Error(`Dialogue ${number}: expected four spoken choices and replies`);
  return [Number(number),Array.from({length:4},(_,i)=>({text:`「${parts[i*2]}」`,reply:parts[i*2+1]}))];
}));
