const dailyRows = text => text.trim().split('\n').map(line => {
 const [index,supportReply,everydayReply,...parts]=line.split('|');
 if(parts.length!==6)throw new Error(`Daily ${index}: expected three alternative pairs`);
 return {index:Number(index),supportReply,everydayReply,alternatives:Array.from({length:3},(_,i)=>({text:`「${parts[i*2]}」`,reply:parts[i*2+1]}))};
});
